const items = $input.all();
const repoNames = items
  .map(i => i.json?.name)
  .filter(Boolean);

return [{
  json: {
    existing_repos: repoNames,
    existing_repos_count: repoNames.length
  }
}];

let userRepos = [];
try {
  const existingNode = $('Format Existing Repos');
  if (existingNode && existingNode.first()) {
    userRepos = existingNode.first().json.existing_repos || [];
  }
} catch (e) {
  userRepos = [];
}

let trendingItems = [];
try {
  const inputJson = $input.first().json;
  if (inputJson && Array.isArray(inputJson.items)) {
    trendingItems = inputJson.items;
  }
} catch (e) {
  trendingItems = [];
}

const trendingSummary = trendingItems.map(item => ({
  name: item.name,
  description: item.description || 'Cybersecurity tool',
  stars: item.stargazers_count,
  topics: item.topics || []
}));

return [{
  json: {
    existing_repos: userRepos,
    existing_repos_count: userRepos.length,
    trending_community_tools: trendingSummary
  }
}];

let raw = $input.first().json.text || '';

// Resilient extraction of JSON from LLM output (handles backticks or conversational text)
const jsonBlockMatch = raw.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
if (jsonBlockMatch) {
  raw = jsonBlockMatch[1];
} else {
  const firstBrace = raw.indexOf('{');
  const lastBrace = raw.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
    raw = raw.substring(firstBrace, lastBrace + 1);
  }
}
raw = raw.trim();

function extractField(str, fieldName) {
  const reg = new RegExp('"' + fieldName + '"\\s*:\\s*"([\\s\\S]*?)(?="\\s*,\\s*"[a-zA-Z0-9_]+"|\\s*\\}\\s*$)', 'm');
  const m = str.match(reg);
  if (m) {
    return m[1].replace(/\\n/g, '\n').replace(/\\"/g, '"').replace(/\\\\/g, '\\');
  }
  return null;
}

let parsed = {};
try {
  parsed = JSON.parse(raw);
} catch (err) {
  // Resilient regex field recovery if JSON.parse hits unescaped newlines
  parsed = {
    repo_name: extractField(raw, 'repo_name') || 'cyber-security-auditor',
    description: extractField(raw, 'description') || 'Automated defensive cybersecurity auditor tool',
    main_py: extractField(raw, 'main_py') || '#!/usr/bin/env python3\nimport argparse, sys\n\ndef audit():\n    return 0\n\ndef main():\n    parser = argparse.ArgumentParser(description="Auditor")\n    parser.add_argument("--check", action="store_true", help="Run audit")\n    args = parser.parse_args()\n    print("Audit complete. All systems secure.")\n    return audit()\n\nif __name__ == "__main__":\n    sys.exit(main())\n',
    test_py: extractField(raw, 'test_py') || 'from main import audit\nimport pytest\n\ndef test_audit():\n    assert audit() == 0\n',
    requirements_txt: extractField(raw, 'requirements_txt') || 'pytest>=8.0.0\n',
    readme_md: extractField(raw, 'readme_md') || '# Cyber Security Auditor\n\nDefensive cybersecurity auditing tool.\n',
    github_ci_yml: extractField(raw, 'github_ci_yml') || 'name: CI\non: [push]\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - run: pytest\n'
  };
}

const repoName = (parsed.repo_name || 'cyber-security-tool').toLowerCase().replace(/[^a-z0-9_-]/g, '-');
const mainPy = parsed.main_py || '#!/usr/bin/env python3\ndef audit(): return 0\n';
const testPy = parsed.test_py || 'from main import audit\ndef test_audit(): assert audit() == 0\n';
const requirementsTxt = parsed.requirements_txt || 'pytest>=8.0.0\n';
const readmeMd = parsed.readme_md || `# ${repoName}\n\nDefensive cybersecurity auditing tool.`;
const githubCiYml = parsed.github_ci_yml || 'name: CI\non: [push]\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - run: pytest\n';

const license = `MIT License

