copies or substantial portions of the Software.

THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR
IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,
FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE
AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER
LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,
OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE
SOFTWARE.`;

const gitignore = `__pycache__/
*.py[cod]
*$py.class
.pytest_cache/
.coverage
htmlcov/
dist/
build/
*.egg-info/
.env
.venv
env/
venv/
.DS_Store
`;

return [{
  json: {
    repo_name: repoName,
    description: parsed.description || `Defensive security tool: ${repoName}`,
    main_py: mainPy,
    test_py: testPy,
    requirements_txt: requirementsTxt,
    readme_md: readmeMd,
    github_ci_yml: githubCiYml,
    license: license,
    gitignore: gitignore,
    b64_main: Buffer.from(mainPy, 'utf-8').toString('base64'),
    b64_test: Buffer.from(testPy, 'utf-8').toString('base64'),
    retry_count: 0
  }
}];

const base = $('Parse Code & Prepare Sandbox').first().json;
let execOut = $input.first().json.stdout || '{}';
let testResult = {};

try {
  testResult = JSON.parse(execOut.trim());
} catch (e) {
  testResult = {
    test_exit_code: 1,
    stdout: execOut,
    stderr: $input.first().json.stderr || e.message,
    repo_name: base.repo_name,
    retry_count: 0
  };
}

const currentMain = testResult.b64_main
  ? Buffer.from(testResult.b64_main, 'base64').toString('utf-8')
  : base.main_py;

return [{
  json: {
    ...base,
    repo_name: testResult.repo_name || base.repo_name,
    main_py: currentMain,
    b64_main: Buffer.from(currentMain, 'utf-8').toString('base64'),
    test_exit_code: Number(testResult.test_exit_code ?? 1),
    stdout: testResult.stdout || '',
    stderr: testResult.stderr || '',
    retry_count: Number(testResult.retry_count ?? base.retry_count ?? 0)
  }
}];

const prev = $('Evaluate Pytest Output').first().json;
let fixedCode = $input.first().json.text || '';
const codeMatch = fixedCode.match(/```(?:python)?\s*([\s\S]*?)\s*```/);
if (codeMatch) {
  fixedCode = codeMatch[1];
}
fixedCode = fixedCode.trim();

const newRetry = (Number(prev.retry_count) || 0) + 1;

return [{
  json: {
    ...prev,
    main_py: fixedCode,
    b64_main: Buffer.from(fixedCode, 'utf-8').toString('base64'),
    retry_count: newRetry
  }
}];

return [{
  json: {
    status: 'FAILED_AFTER_MAX_RETRIES',
    repo_name: $json.repo_name,
    retries_attempted: $json.retry_count,
    last_stdout: $json.stdout,
    last_stderr: $json.stderr,
    timestamp: new Date().toISOString()
  }
}];

const data = $('Evaluate Pytest Output').first().json;
const repoResp = $input.first().json;
const owner = repoResp.owner?.login || repoResp.full_name?.split('/')[0] || '4li466as';
const repo = data.repo_name;

const files = [
  { path: 'main.py', content: data.main_py, message: 'feat: add main tool CLI script' },
  { path: 'tests/test_main.py', content: data.test_py, message: 'test: add pytest test suite' },
  { path: 'requirements.txt', content: data.requirements_txt, message: 'chore: add pinned dependencies' },
  { path: 'README.md', content: data.readme_md, message: 'docs: add professional documentation' },
  { path: 'LICENSE', content: data.license, message: 'chore: add MIT license' },
  { path: '.gitignore', content: data.gitignore, message: 'chore: add standard python gitignore' },
  { path: '.github/workflows/ci.yml', content: data.github_ci_yml, message: 'ci: add GitHub Actions CI pipeline' }
];

return files.map(f => ({
  json: {
    owner: owner,
    repo_name: repo,
    file_path: f.path,
    commit_message: f.message,
    b64_content: Buffer.from(f.content || '', 'utf-8').toString('base64')
  }
}));

const repoInfo = $('Prepare File Commits').first().json;
return [{
  json: {
    owner: repoInfo.owner,
    repo_name: repoInfo.repo_name,
    status: 'All files successfully committed'
  }
}];

const info = $('Aggregate Before Topics').first().json;
return [{
  json: {
    success: true,
    repository: `${info.owner}/${info.repo_name}`,
    url: `https://github.com/${info.owner}/${info.repo_name}`,
    topics: ["cybersecurity", "python", "appsec", "security-tools"],
    published_at: new Date().toISOString()
  }
}];
